const text = $('Mapear Campos').first().json.message || '';

const lines = text
  .split('\n')
  .map(l => l.trim())
  .filter(l => l);

const result = [];

for (const line of lines) {

  // URL
  const urlMatch = line.match(/https?:\/\/[^\s,]+/i);

  if (!urlMatch) continue;

  const url = urlMatch[0];

  // CUPOM
  let cupom = null;

  const cupomMatch = line.match(
    /cupom\s+(.+?)(?=,\s*(?:desc|desconto|off|descontar)\b|$)/i
  );

  if (cupomMatch && cupomMatch[1]) {
    cupom = cupomMatch[1].trim();
  }

  // DESCONTO
  let desconto = null;

  // aceita:
  // desc 12%
  // desconto 10
  // off 20%
  // descontar 15
  const percentMatch = line.match(
    /\b(?:desconto|off|descontar|desc)\s*(\d+(?:[.,]\d+)?)\s*%/i
  );

  if (percentMatch) {
    desconto = percentMatch[1] + "%";
  } else {

    const numberMatch = line.match(
      /\b(?:desconto|off|descontar|desc)\s*(\d+(?:[.,]\d+)?)/i
    );

    if (numberMatch) {
      desconto = parseFloat(
        numberMatch[1].replace(",", ".")
      );
    }
  }

  result.push({
    json: {
      url,
      cupom,
      desconto,
      chatId: $('Mapear Campos').first().json.chatId,
      instance: $('Mapear Campos').first().json.session
    }
  });
}

return result;

const item = $input.first().json;
const original = $('Loop de Agendamentos').item.json;
return {
   json: {
      ...item,
      id_agendamento: original.id,
      cupom: original.cupom,
      desconto: original.desconto,
      url: original.url,
      chatId: original.chatId,
      instance: original.instance
   }
};

const ACCEPTED_EXTENSIONS = ['jpg', 'jpeg', 'png'];
let items = $input.first().json.items || [];
for (const item of items) {
  const imageUrl = item.imagem_url;
  if (!imageUrl || typeof imageUrl !== 'string') {
    item.imagem_url_converted = null;
    continue;
  }
  const [baseUrl, queryString] = imageUrl.split('?');
  const parts = baseUrl.split('.');
  if (parts.length < 2) {
    item.imagem_url_converted = imageUrl;
    continue;
  }
  const currentExtension = parts.pop().toLowerCase();
  if (ACCEPTED_EXTENSIONS.includes(currentExtension)) {
    item.imagem_url_converted = imageUrl;
  } else {
    const newBaseUrl = [...parts, 'jpg'].join('.');
    item.imagem_url_converted = queryString ? `${newBaseUrl}?${queryString}` : newBaseUrl;
  }
}
return [{ json: { items } }];

let text = $input.first().json.output || '';

text = text
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let parsed_array = [];

try {
  parsed_array = JSON.parse(text);
} catch (e) {
  parsed_array = [];
}

// garante que os campos existem (opcional, mas recomendado)
parsed_array = parsed_array.map(item => ({
  texto_formatado: item.texto_formatado || '',
  chatId: item.chatId || null,
  instance: item.instance || null,
  imagem_url_converted: item.imagem_url_converted || null,
  id_agendamento: item.id_agendamento || null
}));

return parsed_array.map(item => ({
  json: item
}));

function parseMoney(value) {
	if (!value) return 0;
	return parseFloat(value.toString().replace("R$", "").replace(/\./g, "").replace(",", ".").trim());
}
function formatBRL(value) {
	return "R$ " + value.toFixed(2).replace(".", ",").replace(/\B(?=(\d{3})+(?!\d))/g, ".");
}

let items = $input.first().json.items || [];
for (let item of items) {
    let rawDesconto = item.desconto;
    let precoStr = item.preco_atual || '0';
    let preco = parseMoney(precoStr);
    let novoPreco = preco;

    if (rawDesconto) {
        let isPercent = false;
        let valorDesconto = 0;
        if (typeof rawDesconto === "string") {
            let desc = rawDesconto.trim();
            if (desc.includes("%")) {
                isPercent = true;
                valorDesconto = parseFloat(desc.replace("%", "").replace(",", "."));
            } else {
                valorDesconto = parseFloat(desc.replace(",", "."));
            }
        }
        else if (typeof rawDesconto === "number") {
            valorDesconto = rawDesconto;
        }

        if (!isNaN(valorDesconto)) {
            if (isPercent) novoPreco = preco - (preco * valorDesconto / 100);
            else novoPreco = preco - valorDesconto;
        }
    }
    if (novoPreco < 0) novoPreco = 0;
    item.preco_atual = formatBRL(novoPreco);
}
return [{ json: { items } }];

const message = $json.message || "";

const agora = /\bagora\b/i;

const contagem = /\bcontagem\b/i;

let tipoFluxo = "agendamento";

if (agora.test(message)) {
  tipoFluxo = "agora";
} else if (contagem.test(message)) {
  tipoFluxo = "contagem"
}

return [
  {
    ...$json,
    tipoFluxo
  }
];

const ACCEPTED_EXTENSIONS = ['jpg', 'jpeg', 'png'];

for (const item of $input.all()) {
  const imageUrl = item.json.imagem_url;

  if (!imageUrl || typeof imageUrl !== 'string') {
    item.json.imagem_url_converted = null;
    continue;
  }

  // Separa URL base e query string
  const [baseUrl, queryString] = imageUrl.split('?');

  // Separa partes pelo ponto
  const parts = baseUrl.split('.');

  if (parts.length < 2) {
    // URL sem extensão clara
    item.json.imagem_url_converted = imageUrl;
    continue;
  }

  const currentExtension = parts.pop().toLowerCase();

  if (ACCEPTED_EXTENSIONS.includes(currentExtension)) {
    // Já é um formato aceito pelo WhatsApp
    item.json.imagem_url_converted = imageUrl;
  } else {
    // Força JPG
    const newBaseUrl = [...parts, 'jpg'].join('.');
    item.json.imagem_url_converted = queryString
      ? `${newBaseUrl}?${queryString}`
      : newBaseUrl;
  }
}

return $input.all();

