const text =
  $json.body?.message ||
  $json.message ||
  $json.text ||
  '';

// Regex genérica para URLs
const urlRegex = /(https?:\/\/[^\s]+)/g;
const urls = text.match(urlRegex);

// Se não tiver URL
if (!urls || urls.length === 0) {
  return [
    {
      json: {
        hasUrl: false,
        cupom: null,
        desconto: null
      }
    }
  ];
}

// Domínios permitidos (afiliados)
const allowedPatterns = [
  /^https?:\/\/(www\.)?amzn\.to\/.+/i,
  /^https?:\/\/(www\.)?meli\.la\/.+/i,
  /^https?:\/\/(www\.)?mercadolivre\.com\/sec\/.+/i,
  /^https?:\/\/(www\.)?amazon\.com\.br\/dp\/[A-Z0-9]+/i
];

// Procura URL válida
const validUrl = urls.find(url =>
  allowedPatterns.some(pattern => pattern.test(url))
);

// 🔎 Detectar CUPOM
let cupom = null;

const cupomRegex = /\b(?:cupom|codigo|código)\s*:?\s*([a-z0-9\-]+)/i;
const cupomMatch = text.match(cupomRegex);

if (cupomMatch && cupomMatch[1]) {
  cupom = cupomMatch[1].toUpperCase();
}

// 🔎 Detectar DESCONTO
let desconto = null;

// primeiro tenta percentual
const percentMatch = text.match(/(\d+(?:[.,]\d+)?)\s*%/);

if (percentMatch) {
  desconto = percentMatch[1] + "%";
} else {
  // tenta número solto (ex: "desconto 12")
  const numberMatch = text.match(/\b(?:desconto|off|descontar|desc)\s*(\d+(?:[.,]\d+)?)/i);
  if (numberMatch) {
    desconto = parseFloat(numberMatch[1].replace(",", "."));
  }
}

// Se não tiver URL válida
if (!validUrl) {
  return [
    {
      json: {
        hasUrl: false,
        cupom,
        desconto
      }
    }
  ];
}

// Retorno final
return [
  {
    json: {
      hasUrl: true,
      url: validUrl,
      cupom,
      desconto
    }
  }
];

function parseMoney(value) {
	if (!value) return 0;
	return parseFloat(
		value
			.toString()
			.replace("R$", "")
			.replace(/\./g, "")
			.replace(",", ".")
			.trim()
	);
}

function formatBRL(value) {
	return "R$ " + value
		.toFixed(2)
		.replace(".", ",")
		.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
}

const descontoRaw = $('Montar JSON').first().json.desconto;

for (const item of $input.all()) {
	const precoStr = item.json.preco_atual;
	const preco = parseMoney(precoStr);

	let novoPreco = preco;

	if (descontoRaw !== undefined && descontoRaw !== null && descontoRaw !== "") {

		let isPercent = false;
		let valorDesconto = 0;

		// 🔥 Se for STRING
		if (typeof descontoRaw === "string") {
			const desc = descontoRaw.trim();

			if (desc.includes("%")) {
				isPercent = true;
				valorDesconto = parseFloat(desc.replace("%", "").replace(",", "."));
			} else {
				valorDesconto = parseFloat(desc.replace(",", "."));
			}
		}

		// 🔥 Se for NUMBER
		else if (typeof descontoRaw === "number") {
			valorDesconto = descontoRaw;
		}

		// aplica regra
		if (!isNaN(valorDesconto)) {
			if (isPercent) {
				novoPreco = preco - (preco * valorDesconto / 100);
			} else {
				novoPreco = preco - valorDesconto;
			}
		}
	}

	if (novoPreco < 0) novoPreco = 0;

	item.json.preco_atual = formatBRL(novoPreco);
}

return $input.all();

let mensagem;

mensagem = `estou sem links para gerar os anúncios...

Por favor, assim que puder, me envie links para mantermos nossos ganhos, tá bom? 😉 `;

return [{ mensagem }];

const agoraSP = new Date(
  new Date().toLocaleString("en-US", { timeZone: "America/Sao_Paulo" })
);

let horaAtual = agoraSP.getHours();
const minutos = agoraSP.getMinutes();

// ⏱️ Arredonda pra próxima hora
if (minutos > 0) {
  horaAtual += 1;
}

// 🔒 Janela 08h às 20h
if (horaAtual < 8) horaAtual = 8;

let mensagem;

// 🚫 Fora do horário
if (horaAtual >= 21) {
  mensagem = `horário de envio automático já encerrou por hoje. ⛔

Voltamos amanhã a partir das 8h! 🌅`;

} else {

  const count = Number($('Contagem de links meta diária').first().json.count);

  const numero_link_pendentes = Number($('Contagem de links pendentes atual').first().json.numero_link_pendentes);

  // ⏱️ Tempo restante do dia
  const horasRestantes = 21 - horaAtual;

  // 🔢 Capacidade de envio restante (5 por hora)
  const capacidadeRestante = horasRestantes * 5;

  // 📦 Links que ainda precisam ser enviados
  const linksFaltantes = 65 - count;

  let mensagem_meta;
  let ultimaHoraEnvio;

  // ✅ Se já bateu a meta
  if (linksFaltantes <= 0) {

    mensagem_meta = `🎉 Meta diária já foi atingida, não é necessário enviar mais links hoje!`;

  } 
  // ⚠️ Se não dá tempo de enviar tudo hoje
  else if (numero_link_pendentes > capacidadeRestante) {

    ultimaHoraEnvio = 21;

    mensagem_meta = `Já recebi links o suficiente! Não será possível enviar todos hoje. ⚠️ 

Restam apenas *${capacidadeRestante} anúncios* para serem gerados até às *${ultimaHoraEnvio}h* e tenho ${numero_link_pendentes} ainda pendentes na fila! ⏰`;

  } 
  // 🚀 Fluxo normal
  else {

    const horasNecessarias = Math.ceil(numero_link_pendentes / 5);

    ultimaHoraEnvio = horaAtual + horasNecessarias - 1;

    mensagem_meta = `Precisamos de mais *${capacidadeRestante - numero_link_pendentes} links* para manter os 5 anúncios por hora até às 21h. 🎯

O último horário de envio previsto hoje será às *${ultimaHoraEnvio}h*! ⏰`;
  }

  mensagem = `recebi até o momento *${count} de 65 links* previstos para hoje! 📌

${mensagem_meta}

*Pra cima que foguete não tem ré! (exceto o do Elon Musk kkk)* 🚀`;
}

return [{ mensagem }];
